import{_ as e,o,c as l,a5 as t}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 36 话 dialog 元素：原生模态一句话入场","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.36-dialog.md","filePath":"comics/html/EP.36-dialog.md","lastUpdated":1793421609000}'),d={name:"comics/html/EP.36-dialog.md"};function r(c,a,i,s,n,h){return o(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-36-话-dialog-元素-原生模态一句话入场" tabindex="-1">漫画 · 第 36 话 dialog 元素：原生模态一句话入场 <a class="header-anchor" href="#漫画-·-第-36-话-dialog-元素-原生模态一句话入场" aria-label="Permalink to &quot;漫画 · 第 36 话 dialog 元素：原生模态一句话入场&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/12-dialog">docs/html/12-dialog.md</a> ｜ 原画：<a href="./EP.36-dialog.svg">EP.36-dialog.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话痛点担当。自研 Modal 组件 400 行：portal 挂 body、z-index 战争、80 行 focus trap、Esc 与遮罩监听，仍叠错序。</li><li><strong>标签君</strong>：HTML5 结构师，掏出自己的本家元素 <code>&lt;dialog&gt;</code>——<code>showModal()</code> 一句进入 top layer，页面自动惰性化，模态语义浏览器原生实现。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱被手搓模态折磨：焦点漏到背景、两层遮罩叠错序、读屏器读出背景内容，无障碍审计过不去。标签君请出 <code>&lt;dialog&gt;</code>——<code>showModal()</code> 自动 top layer + inert 页面 + 焦点圈禁 + Esc 关闭；<code>form method=&quot;dialog&quot;</code> 让按钮 value 直接写入 returnValue，确认/取消分流零 JS。码叔最后补刀：进出场动画交给 <code>@starting-style</code> 三件套，分工记牢——要答案用 dialog，展示信息用 popover。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>自研 Modal 四件套：portal 挂载、z-index 9999、focus trap、Esc/遮罩监听。叠加痛苦：焦点漏背景、遮罩叠错序、读屏器读背景、动画时长 CSS/JS 双写——400 行代码仍有 bug。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>showModal()</code> 一句全包：top layer 最顶层（不受 z-index 战争影响）、页面自动 inert（不可点不可聚焦）、焦点圈禁、Esc 触发 cancel 后默认关闭；<code>::backdrop</code> 纯 CSS 定制遮罩模糊。<code>form method=&quot;dialog&quot;</code>：点按钮即关窗，value 自动写入 returnValue。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：确认对话框（零 JS 分流）、拦截 Esc（cancel 可 preventDefault，保护未保存表单）、closedby 轻关闭（<code>any</code> 点外部关 / <code>none</code> 强制确认）、进出场动画（<code>@starting-style</code> + <code>allow-discrete</code>，遮罩同步淡入淡出）。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>showModal() 进 top layer：页面自动 inert、焦点圈禁、Esc 关闭、::backdrop 可定制。</li><li>form method=&quot;dialog&quot;：按钮 value 自动写入 returnValue，确认/取消分流零 JS。</li><li>分工：打断流程要答案用 dialog，顺手展示补充信息用 popover。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：Esc 关闭模态框时，<code>cancel</code> 和 <code>close</code> 事件谁先谁后？如何阻止 Esc 关闭？</p><p><strong>答</strong>：Esc → 先触发 <code>cancel</code>，随后默认执行 <code>close</code>。在 <code>cancel</code> 里 <code>preventDefault()</code> 即可阻止后续关闭（<code>close</code> 不再触发）——未保存表单保护就靠它。<code>close</code> 事件本身不可拦截。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>确认分流 + 拦截 Esc + closedby 轻关闭 + 进出场动画 + 非模态抽屉：<a href="./../../examples/html/12-dialog/index-01-dialog.html">examples/html/12-dialog/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>CSS 篇与 HTML 篇的现代扩展持续进行中——锚点定位、Popover、@starting-style、Observer、滚动吸附、dialog 已就位，下一站将由大家票选：View Transitions 进阶还是 CSS 函数新玩法？</p>',22)])])}const g=e(d,[["render",r]]);export{p as __pageData,g as default};
